import {renderHeader,renderFooter,escapeHTML as e} from '../explorer-views.js';
import {startingPointBank as bank,startingQuestions,startingOption,text,selections} from './starting-point.js';
export const ui=(locale,en,zh,ms)=>({en,'zh-CN':zh,ms})[locale]||en;
const sections=[['Understand Your Concerns','了解你真正的困惑','Fahami kebimbangan anda'],['Understand Your Starting Point','了解你目前拥有的能力','Fahami titik permulaan anda'],['Understand Your Ambitions','了解你真正想走向哪里','Fahami cita-cita anda'],['A Little More Context','进一步了解你的处境','Sedikit lagi konteks'],['Your Story','你的补充','Cerita anda']];
function choices(q,intake,locale,part){
 const multiple=['multi','priority'].includes(q.kind),value=multiple?selections(intake.answers[q.id]):part?intake.answers[q.id]?.[part]:intake.answers[q.id];
 return `<div class="starting-choices">${q.options.map(o=>{
  const checked=multiple?value?.includes(o.id):value===o.id;
  return `<label class="starting-choice ${checked?'is-selected':''}"><input type="${multiple?'checkbox':'radio'}" name="${e(q.id+(part?'.'+part:''))}" data-starting-field="${e(q.id+(part?'.'+part:''))}" value="${e(o.id)}" ${checked?'checked':''} ><span><strong>${e(text(o.label,locale))}</strong>${o.description?`<small>${e(text(o.description,locale))}</small>`:''}</span><span class="starting-choice-check" aria-hidden="true">${checked?'✓':'+'}</span></label>`;
 }).join('')}</div>`;
}
function controls(q,intake,locale){
 const L=(en,zh,ms)=>ui(locale,en,zh,ms);
 if(q.kind==='story')return `<p>${L('Optional. You can skip this. Your story stays on this device unless you separately consent to sharing it with optional AI.','选填，可以直接跳过。补充内容保留在本机，只有另行明确同意后才会随可选 AI 分析发送。','Pilihan. Anda boleh melangkau. Cerita kekal pada peranti ini kecuali anda memberi persetujuan berasingan untuk AI pilihan.')}</p><textarea id="starting-story" name="story" data-starting-story maxlength="1500" rows="6" placeholder="${e(text(bank.story.placeholder,locale))}" aria-labelledby="starting-heading">${e(intake.story)}</textarea><small class="starting-story-count">${intake.story.length} / 1500</small>`;
 if(q.kind==='matrix')return `<p>${L('Answer from actual learning or work experience, not your hoped-for future level. This is a self-report, not a verified skills test.','请根据真实学习或工作经历作答，而不是根据你觉得自己未来可能做到什么来选择。这是自述能力，不是已验证的专业能力。','Jawab berdasarkan pengalaman belajar atau kerja sebenar, bukan tahap masa depan yang diharapkan. Ini laporan kendiri, bukan ujian kemahiran disahkan.')}</p><div class="starting-matrix">${q.rows.map(row=>`<fieldset><legend>${e(text(row.label,locale))}</legend><div class="starting-matrix-options">${q.options.map(o=>`<label class="${intake.answers.Q05?.[row.id]===o.id?'is-selected':''}"><input type="radio" name="Q05.${row.id}" data-starting-field="Q05.${row.id}" value="${o.id}" ${intake.answers.Q05?.[row.id]===o.id?'checked':''}><span>${e(text(o.label,locale))}</span></label>`).join('')}</div></fieldset>`).join('')}</div><details class="starting-level-guide"><summary>${L('What each level means','各等级的含义','Maksud setiap tahap')}</summary>${q.options.map(o=>`<p><strong>${e(text(o.label,locale))}</strong> — ${e(text(o.description,locale))}</p>`).join('')}</details>`;
 if(q.kind==='priority'||q.kind==='multi'){
  const values=selections(intake.answers[q.id]);
  const summary=`<div class="intake-selection-meta"><span role="status">${values.length} / ${q.maxSelections||4} ${L('selected','已选','dipilih')}</span><span>${L('Click a selected choice to remove it. Exclusive options replace other choices.','点击已选项即可取消；互斥选项会替换其他选择。','Klik pilihan dipilih untuk membuangnya. Pilihan eksklusif menggantikan pilihan lain.')}</span></div>`;
  const primary=q.kind==='priority'?`<label class="starting-secondary" for="primary-${q.id}">${q.id==='Q09'?L('Primary reference market','主要参考市场','Pasaran rujukan utama'):L('My first priority','首要关注项','Keutamaan pertama saya')}</label><select id="primary-${q.id}" data-starting-field="${q.id}.primary" name="${q.id}.primary"><option value="">${L('Choose from your selected options','从已选项中明确指定','Pilih daripada pilihan anda')}</option>${q.options.filter(o=>values.includes(o.id)).map(o=>`<option value="${o.id}" ${intake.answers[q.id]?.primary===o.id?'selected':''}>${e(text(o.label,locale))}</option>`).join('')}</select>`:'';
  return summary+choices(q,intake,locale)+primary;
 }
 return choices(q,intake,locale);
}
export function renderStartingPoint(intake,locale='en',error='',motion=''){
 const L=(en,zh,ms)=>ui(locale,en,zh,ms),questions=startingQuestions(intake.answers),q=questions[intake.index];
 const top=`<div class="starting-top"><button class="text-button" type="button" data-combined-action="${intake.screen==='intro'?'home':'starting-back'}">← ${L(intake.screen==='intro'?'Back to home':'Back',intake.screen==='intro'?'返回首页':'上一题',intake.screen==='intro'?'Kembali ke laman utama':'Kembali')}</button><span>${L('Your future, in context','从你的真实处境出发','Masa depan anda, dalam konteks')}</span></div>`;
 let body;
 if(intake.screen==='intro')body=`<section class="starting-card starting-intro"><span class="kicker">AI CAREER NAVIGATOR</span><h1 id="starting-heading" tabindex="-1">${L('Your Future Starts With Understanding You','在规划未来之前，我们想先了解你。','Masa depan bermula dengan memahami diri anda.')}</h1><p class="hero-lede">${L('AI is changing careers, but everyone faces different challenges.','AI 正在改变职业世界，但每个人面对的挑战都不同。','AI mengubah dunia kerjaya, tetapi cabaran setiap orang berbeza.')}</p><p>${L('You may worry that your skills will lose value, feel unsure about career fit, or see AI and international opportunities without knowing where to begin.','也许你担心现在学习的技能很快失去价值，也许你不知道自己适合什么职业，或者你看到了 AI 和国际市场创造的新机会，却不知道该从哪里开始。','Anda mungkin bimbang kemahiran kehilangan nilai, belum pasti arah kerjaya, atau melihat peluang AI dan antarabangsa tanpa mengetahui langkah pertama.')}</p><p>${L('This is not an exam. There are no right answers. We want to understand your situation, then connect your characteristics with career information to help you find a next step.','这不是一场考试，也没有标准答案。我们希望先了解你的真实处境，再结合你的个人特点与职业市场信息，帮助你找到下一步。','Ini bukan peperiksaan dan tiada jawapan betul. Kami mahu memahami keadaan anda, kemudian mengaitkan ciri diri dengan maklumat kerjaya untuk membantu menentukan langkah seterusnya.')}</p><div class="starting-meta">${L('4–6 minutes · 11 core questions · up to 2 follow-ups','预计用时：4–6 分钟 · 11 个核心问题 · 最多 2 个补充问题','4–6 minit · 11 soalan teras · sehingga 2 soalan susulan')}</div><button class="button primary" data-combined-action="starting-next">${L('Let’s begin','开始了解自己','Mari bermula')} ↗</button></section>`;
 else if(intake.screen==='bridge')body=`<section class="starting-card"><span class="kicker">${L('Your starting point','你的起点','Titik permulaan anda')}</span><h1 id="starting-heading" tabindex="-1">${L("Here’s What We Understand About You",'我们初步了解到的你','Inilah yang kami fahami tentang anda')}</h1><p class="hero-lede">${L('We now have context about your current stage, main concern, reported experience and goals. Next, a few short questions will explore career interests, work preferences and AI collaboration habits.','根据你的回答，我们初步了解到你的当前阶段、主要困惑、已有经历与发展目标。接下来，我们希望通过一些简短问题，进一步了解你的职业兴趣、工作偏好和 AI 协作习惯。','Kami kini mempunyai konteks tahap semasa, kebimbangan utama, pengalaman dilaporkan dan matlamat anda. Seterusnya, beberapa soalan ringkas akan meneroka minat kerjaya, keutamaan kerja dan amalan kerjasama AI.')}</p><dl class="starting-bridge-summary">${[['Q01',null,L('Current stage','当前阶段','Tahap semasa')],['Q02','primary',L('Main concern','主要困惑','Kebimbangan utama')],['Q08',null,L('Desired outcome','希望得到的结果','Hasil diharapkan')],['Q09',null,L('Market perspective','市场视角','Perspektif pasaran')]].map(([id,part,label])=>`<div><dt>${label}</dt><dd>${e(startingOption(intake,id,locale,part))}</dd></div>`).join('')}</dl><p>${L('Your current background does not decide your future direction. You can explore directions before trying one.','当前背景不替你决定未来方向。你可以先了解各方向，再选择一个开始体验。','Latar semasa tidak menentukan arah masa depan. Anda boleh meneroka arah sebelum mencubanya.')}</p><button class="button primary" data-combined-action="starting-continue">${L('Explore career directions','探索职业方向','Terokai arah kerjaya')} ↗</button></section>`;
 else body=`<section class="starting-card" data-starting-question="${q.id}"><div class="starting-progress-top"><span>${q.id} · ${ui(locale,...sections[q.section])}</span><span>${intake.index+1} / ${questions.length}</span></div><div class="progress-track" role="progressbar" aria-label="${L('Questionnaire progress','问卷进度','Kemajuan soal selidik')}" aria-valuemin="0" aria-valuemax="${questions.length}" aria-valuenow="${intake.index+1}"><div style="width:${(intake.index+1)/questions.length*100}%"></div></div><h1 id="starting-heading" tabindex="-1">${e(text(q.prompt,locale))}</h1><form id="starting-point-form" novalidate>${controls(q,intake,locale)}${error?`<p class="field-error" role="alert">${error==='multi'?L('Choose at least one option within the selection limit.','请在数量限制内至少选择一项。','Pilih sekurang-kurangnya satu dalam had pilihan.'):error==='matrix'?L('Choose one level for each of the four aspects.','请为四个方面各选择一项。','Pilih satu tahap bagi setiap empat aspek.'):L('Complete your selection and specify the primary item where requested.','请完成选择，并按要求明确指定首要项。','Lengkapkan pilihan dan tetapkan pilihan utama jika diminta.')}</p>`:''}<div class="starting-actions"><button class="button secondary" type="button" data-combined-action="starting-back">← ${L('Back','上一题','Kembali')}</button><button class="button primary" type="submit">${L(q.kind==='story'&&!intake.story?'Skip and continue':'Continue',q.kind==='story'&&!intake.story?'跳过并继续':'下一题',q.kind==='story'&&!intake.story?'Langkau dan teruskan':'Teruskan')} ↗</button></div></form></section>`;
 return renderHeader({report:null})+`<main class="shell starting-shell">${top}<div class="starting-transition ${motion?'is-moving '+motion:''}" data-starting-transition>${body}</div></main>`+renderFooter();
}
